/*
 * kernel/include/gfx_font.h - the bitmap font data format (stage G4 of issue #7).
 *
 * The data in kernel/gfx/font_noto_mono.c is generated by tools/fontgen/gen_font.py from Noto Sans Mono v2.014 (SIL Open Font
 * License 1.1; notices in third_party/fonts/NotoSansMono/). Printable ASCII only: U+0020..U+007E. Hindi, Gujarati and every other
 * script are NOT supported and are drawn as a visible missing-glyph box; there is no shaping, no bidirectional text and no
 * combining marks.
 */
#ifndef AURORA_GFX_FONT_H
#define AURORA_GFX_FONT_H
#include <stdint.h>

#define GFX_FONT_REGULAR 400
#define GFX_FONT_BOLD    700

/* One glyph: a w x h 1-bit bitmap, ceil(w/8) bytes per row, bit 7 = leftmost pixel, starting at byte `off` of the face's bits.
 * Its left edge is `xoff` pixels right of the pen position; its top row is `top` pixels above the baseline. w = h = 0 is blank. */
struct gfx_glyph { int8_t xoff; int8_t top; uint8_t w; uint8_t h; uint16_t off; };

struct gfx_font {
    const char *name;
    uint16_t weight;                  /* GFX_FONT_REGULAR or GFX_FONT_BOLD */
    uint8_t size;                     /* nominal pixel size (the em) */
    uint8_t advance;                  /* the fixed pen advance of every glyph, in pixels */
    uint8_t ascent, descent;          /* pixels above and below the baseline */
    uint8_t line_height;              /* distance between baselines of consecutive lines */
    uint8_t first, last;              /* inclusive code point range with glyphs */
    const struct gfx_glyph *glyphs;   /* last - first + 1 entries */
    const uint8_t *bits;
    uint32_t bits_len;
};

extern const struct gfx_font *const gfx_fonts[];
extern const int gfx_font_count;

#endif
